; Enemy kill by a missile
; $5e6a-$5e91

; Kills enemy X (1-4) when its state is $01-$cf: sets the state $d0 (falling) and adds the score. Input from $4200 after the missile test. When the jet is not lost and $af is 0, it starts the noise of SID voice 1 and sets $af to 6 frames.
enemy_kill
; not executed $5e6a-$5e91
        lda enemy_state,x
        beq enemy_kill_done
        cmp #$d0
        bcs enemy_kill_done
        lda #$d0
        sta enemy_state,x
        jsr score_add_kill              ; The score is added also while the jet is lost.
        lda jet_state
        and #$08
        bne enemy_kill_done
        lda kill_sound_timer
        bne enemy_kill_done
        lda #$80                        ; Gate off and on: restarts the noise of voice 1.
        sta VCREG1
        lda #$81
        sta VCREG1
        lda #$06
        sta kill_sound_timer
enemy_kill_done
        rts
